from fractions import Fraction
from typing import List

def geometric(r: Fraction, length: int) -> List[Fraction]:
    return [r ** n for n in range(length)]

def L(a: List[Fraction]) -> List[Fraction]:
    return [a[n + 1] ** 2 - a[n] * a[n + 2] for n in range(len(a) - 2)]

if __name__ == "__main__":
    for r in (Fraction(2), Fraction(3), Fraction(3, 2)):
        seq = geometric(r, 12)
        disc = L(seq)
        assert all(d == 0 for d in disc)
        print(f"r={r}: L(r^n) is identically zero -> infinitely log-concave.")
    print("Geometric sequences sit exactly on the log-concave/log-convex boundary.")

