function DISCRIMINANT(a[0..N+1]):
    out <- empty list
    for n from 0 to N-1:
        out[n] <- a[n+1]^2 - a[n]*a[n+2]
    return out[0..N-1]

function INF_LOG_CONCAVITY_TEST(a, depth):
    cur <- a
    for k from 0 to depth:
        for n, v in enumerate(cur):
            if v < 0: return (k, n, v)   # violation witness
        if len(cur) < 3: break
        cur <- DISCRIMINANT(cur)
    return NONE                          # no violation found

